sections.forEach(section=>{ const el=document.createElement('section'); el.className='exam-section'; el.id=section.id; el.innerHTML=`<div class="section-heading"><span class="section-icon">${section.icon}</span><div class="section-title"><h2>${section.title}</h2><p class="section-summary" data-section-summary="${section.id}">Not recorded</p></div><button class="section-normal" type="button" data-section-normal="${section.id}">Mark routine normal</button><button class="section-toggle" type="button" data-section-toggle="${section.id}" aria-expanded="false">Add detail</button></div><div class="section-content" data-section-content="${section.id}" hidden>${section.groups.map(g=>`<section class="sheet-group" data-group="${slug(`${section.id}-${g.title}`)}"><div class="group-heading"><h3>${g.title}</h3><button type="button" class="group-normal" data-group-normal title="Applies normal values to the selectable routine findings in this group.">Mark routine normal</button></div>${g.fields?g.fields.map(f=>fieldMarkup(section,f)).join(''):tableMarkup(section,g.table,g.title)}</section>`).join('')}</div>`; root.append(el); const tab=document.createElement('button'); tab.type='button';tab.dataset.tab=section.id;tab.textContent=section.title;tab.addEventListener('click',()=>showTab(section.id));nav.append(tab); });
