function showTab(id) { active=id; document.querySelectorAll('.exam-section').forEach(el=>el.hidden=examMode!=='detailed'&&el.id!==id); document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===id)); save(); }
