function showExamMode(mode) { examMode=mode; document.body.dataset.examMode=mode; document.querySelector('#exam-mode-state').value=mode; quickRoot.hidden=mode!=='quick'; pathwayRoot.hidden=mode!=='pathway'; document.querySelectorAll('[data-exam-mode]').forEach(button=>button.classList.toggle('active',button.dataset.examMode===mode)); if(mode==='detailed')applyExamTemplate(); save(); }
function updateSectionSummaries(){document.querySelectorAll('.exam-section').forEach(section=>{const summary=section.querySelector('[data-section-summary]');if(!summary)return;const normal=section.querySelector('.section-normal')?.classList.contains('selected');const recorded=[...section.querySelectorAll('input[type=radio]:checked,input[data-multi-key]:checked,select,[data-key],.power-normal.selected,.visual-row [data-field].selected')].filter(el=>el.matches('select')?Boolean(el.value):el.matches('[data-key]')?!el.matches('input[type=hidden]')&&Boolean(el.value.trim()):true).length;summary.textContent=normal?'✓ Normal confirmed':recorded?`${recorded} finding${recorded===1?'':'s'} recorded`:'Not recorded';section.classList.toggle('has-abnormal-detail',!normal&&recorded>0);});}
function save() { const saved={patient:document.querySelector('#patient').value,date:document.querySelector('#exam-date').value,active}; document.querySelectorAll('input[type=radio]:checked').forEach(el=>saved[el.name]=el.value); document.querySelectorAll('[data-multi-key]').forEach(el=>{const id=el.dataset.multiKey;saved[id]??=[];if(el.checked)saved[id].push(el.value);}); document.querySelectorAll('[data-key]').forEach(el=>saved[el.dataset.key]=el.value); document.querySelectorAll('[data-power-normal]').forEach(el=>saved[`${el.dataset.powerNormal}-normal`]=el.classList.contains('selected')); document.querySelectorAll('[data-power-view]').forEach(el=>{if(el.classList.contains('active'))saved[`${el.dataset.powerView}-view`]=el.dataset.view;}); document.querySelectorAll('.visual-row').forEach(row=>{const id=row.querySelector('[data-field]').dataset.field;saved[id]=[...row.querySelectorAll('[data-field].selected')].map(el=>el.dataset.normal?'Normal':el.dataset.other?'Other':el.dataset.value);}); Object.assign(state,saved); if(!WEBSITE_MODE)localStorage.setItem('neuro-sheet-v2',JSON.stringify(saved)); const chosen=[...document.querySelectorAll('input[type=radio]:checked, input[data-multi-key]:checked, [data-key]')].filter(el=>el.matches('input[type=radio],input[data-multi-key]')||el.value.trim()).length + document.querySelectorAll('[data-power-normal].selected, .visual-row [data-field].selected').length; document.querySelector('#progress').textContent=chosen?`${chosen} item${chosen===1?'':'s'} recorded`:'No tests selected yet'; updateSectionSummaries(); }
function escapeHtml(value) { const el=document.createElement('div'); el.textContent=value; return el.innerHTML; }
function visualFieldLines(row) { const id=row.querySelector('[data-field]').dataset.field, values=state[id]||[], lines=[]; if(values.includes('Normal'))lines.push('Visual fields: Normal'); else {const remaining=values.filter(value=>value!=='Other'), left=new Set(remaining.filter(value=>value.startsWith('Left ')).map(value=>value.slice(5))),right=new Set(remaining.filter(value=>value.startsWith('Right ')).map(value=>value.slice(6))), has=(eye,cells)=>cells.every(cell=>eye.has(cell)); let summary=''; if(has(left,['LU','RU','LL','RL']))summary='complete visual field loss in the left eye'; else if(has(right,['LU','RU','LL','RL']))summary='complete visual field loss in the right eye'; else if(has(left,['LU','LL'])&&has(right,['LU','LL']))summary='left homonymous hemianopia'; else if(has(left,['RU','RL'])&&has(right,['RU','RL']))summary='right homonymous hemianopia'; else if(has(left,['LU','LL'])&&has(right,['RU','RL']))summary='bitemporal hemianopia'; else if(has(left,['RU','RL'])&&has(right,['LU','LL']))summary='binasal hemianopia'; else {const quadrants=[['LU','left superior quadrantanopia'],['LL','left inferior quadrantanopia'],['RU','right superior quadrantanopia'],['RL','right inferior quadrantanopia']]; const match=quadrants.find(([cell])=>left.has(cell)&&right.has(cell)); if(match)summary=`${match[1]} (homonymous)`;} if(!summary&&remaining.length){const names={LU:'upper-left quadrant',RU:'upper-right quadrant',LL:'lower-left quadrant',RL:'lower-right quadrant'};summary=remaining.map(value=>{const [eye,quadrant]=value.split(' ');return `${eye.toLowerCase()} eye ${names[quadrant]} defect`;}).join(', ');} if(summary)lines.push(`Visual fields: ${summary}`); const other=row.querySelector('.other-wrap [data-key]')?.value.trim();if(other)lines.push(`Visual fields: ${other}`);} return lines; }
function powerFieldLines(builder) { const entries=[]; builder.querySelectorAll('[data-power-row]').forEach(row=>{const r=row.querySelector('[data-power-score][data-key$="-r"]').value,l=row.querySelector('[data-power-score][data-key$="-l"]').value,normal=row.querySelector('[data-power-normal]').classList.contains('selected')||(r==='5'&&l==='5');if(normal)entries.push({name:row.dataset.name,normal:true,line:`${row.dataset.name}: 5/5 bilaterally`});else if(r||l)entries.push({name:row.dataset.name,normal:false,line:`${row.dataset.name}: ${r?`R ${r}/5`:''}${r&&l?', ':''}${l?`L ${l}/5`:''}`});}); entries.sort((a,b)=>POWER_ORDER.indexOf(a.name)-POWER_ORDER.indexOf(b.name)); const screenNames=[...builder.querySelectorAll('.power-pane[data-pane="screen"] [data-power-row]')].map(row=>row.dataset.name),screenComplete=screenNames.length>0&&entries.length===screenNames.length&&entries.every(entry=>entry.normal)&&screenNames.every(name=>entries.some(entry=>entry.name===name)); const custom=builder.querySelector('textarea[data-key]')?.value.trim();return [...(screenComplete?['Power: 5/5 bilaterally throughout the screening muscle groups.']:entries.map(entry=>entry.line)),...(custom?[`Power: ${custom}`]:[])]; }
function sensoryMapLines(map) { const data=sensoryMapData(map.querySelector('input[type=hidden][data-key]').value), groups={}; map.querySelectorAll('[data-sensory-region]').forEach(region=>{const finding=data[region.dataset.sensoryRegion];if(finding)(groups[finding]??=[]).push(region.dataset.sensoryLabel);}); const lines=Object.entries(groups).map(([finding,regions])=>`Sensory map: ${finding.toLowerCase()} sensation over ${regions.join(', ')}`); const detail=map.querySelector('.sensory-map-detail').value.trim();if(detail)lines.push(`Sensory map: ${detail}`);return lines; }
function sensoryDrawingLocation(stroke) { const average=stroke.points.reduce((total,[x,y])=>[total[0]+x,total[1]+y],[0,0]).map(total=>total/stroke.points.length),[x,y]=average, front=stroke.view==='Front', right=front?x<75:x>75, side=right?'right':'left'; if(y<22)return `${front?'anterior':'posterior'} forehead`; if(y<34)return `${side} cheek`; if(y<43)return `${side} jaw`; if(y<59&&Math.abs(x-75)<19)return `${front?'anterior chest':'upper back'}`; if(y<87&&Math.abs(x-75)<19)return `${front?'anterior abdomen':'lower back'}`; if(y<67&&Math.abs(x-75)>=19)return `${side} upper arm`; if(y<82&&Math.abs(x-75)>=19)return `${side} forearm`; if(y<91&&Math.abs(x-75)>=19)return `${side} hand`; const legCenter=right?(front?64:86):(front?86:64), outer=right?(front?x<legCenter:x>legCenter):(front?x>legCenter:x<legCenter), surface=outer?'lateral':'medial'; if(y>140)return `${side} ${surface} foot`; if(y>128)return `${side} ${surface} ankle`; if(y>108)return `${side} ${surface} lower leg`; return `${side} thigh`; }
function sensoryDrawingLines(drawing) { const strokes=sensoryDrawingData(drawing.querySelector('input[type=hidden][data-key]').value), groups={}; strokes.forEach(stroke=>{const modality=stroke.modality||'Pinprick',finding=stroke.finding.toLowerCase(),location=sensoryDrawingLocation(stroke),groupKey=`${modality}|${finding}`;(groups[groupKey]??=[]).push(location);}); const lines=Object.entries(groups).map(([key,locations])=>{const [modality,finding]=key.split('|');return `${modality}: ${finding} sensation over ${[...new Set(locations)].join(', ')}`;}); const detail=drawing.querySelector('.sensory-map-detail').value.trim();if(detail)lines.push(detail);return lines; }
function fieldRowLines(row) { const builder=row.querySelector('.power-builder');if(builder)return powerFieldLines(builder);const sensoryDrawing=row.querySelector('.sensory-drawing');if(sensoryDrawing)return sensoryDrawingLines(sensoryDrawing);const sensoryMap=row.querySelector('.sensory-map');if(sensoryMap)return sensoryMapLines(sensoryMap);if(row.classList.contains('visual-row'))return visualFieldLines(row);if(row.classList.contains('visual-acuity-row')){const value=side=>row.querySelector(`[data-key$="-${side}"]`)?.value.trim(), pinhole=side=>row.querySelector(`[data-key$="-${side}-pinhole"]`)?.value.trim(), eye=side=>{const acuity=value(side),ph=pinhole(side);return acuity?`${side.toUpperCase()} ${acuity}${ph?` (pinhole ${ph})`:''}`:'';};const eyes=['r','l'].map(eye).filter(Boolean),glasses=row.querySelector('[data-visual-glasses]')?.classList.contains('selected');return eyes.length?[`Visual acuity: ${eyes.join(', ')}${glasses?' (with glasses)':''}`]:glasses?['Visual acuity assessed with glasses']:[];} const checked=row.querySelector('input[type=radio]:checked');if(checked){const other=checked.value==='Other'?row.querySelector('.other-wrap [data-key]')?.value.trim():'';return [other?`${checked.dataset.label}: ${other}`:`${checked.dataset.label}: ${checked.value}`];} const checkedMulti=[...row.querySelectorAll('input[data-multi-key]:checked')];if(checkedMulti.length){const other=checkedMulti.some(input=>input.value==='Other')?row.querySelector('.other-wrap [data-key]')?.value.trim():'';const values=checkedMulti.filter(input=>input.value!=='Other').map(input=>input.value);if(other)values.push(other);return values.length?[`${checkedMulti[0].dataset.label}: ${values.join(', ')}`]:[];} return [...row.querySelectorAll('[data-key]:not([data-power-score])')].filter(control=>!control.closest('.other-wrap')&&!control.closest('.power-builder')).map(control=>control.value.trim()?`${control.dataset.label}: ${control.value.trim()}`:'').filter(Boolean); }
function linesFor(section) { if(examMode==='quick'){const card=document.querySelector(`[data-quick-section="${section.id}"]`);if(!card)return [];const normal=card.querySelector('[data-key$="-normal"]').value==='true',other=card.querySelector('textarea').value.trim();return other?[other]:normal?[card.dataset.normalLabel]:[];} const sectionElement=document.querySelector(`#${section.id}`);if(sectionElement?.querySelector('.section-normal')?.classList.contains('selected')&&ROUTINE_SECTION_LINES[section.id])return ROUTINE_SECTION_LINES[section.id]; const lines=[]; document.querySelectorAll(`#${section.id} .sheet-group`).forEach(group=>{[...group.children].forEach(child=>{if(child.classList.contains('field-row'))lines.push(...fieldRowLines(child));if(child.classList.contains('power-builder'))lines.push(...powerFieldLines(child));if(child.classList.contains('table-wrap'))child.querySelectorAll('select[data-key]').forEach(select=>{if(select.value)lines.push(`${select.dataset.label}: ${select.value}`);});});}); return [...new Set(lines)]; }
function generateBulletNote(header,dateText) { if(examMode==='pathway'){const pathway=PATHWAYS[examTemplate], groups=[...pathwayRoot.querySelectorAll('.sheet-group')].map(group=>{const lines=[...group.children].flatMap(child=>child.classList.contains('field-row')?fieldRowLines(child):[]);return lines.length?`${group.querySelector('legend').textContent}\n${lines.map(line=>`• ${line}`).join('\n')}`:'';}).filter(Boolean);return `${header}${dateText?` (${dateText})`:''}\n\n${pathway.title}\n\n${groups.length?groups.join('\n\n'):'No findings selected.'}`;} const body=sections.map(section=>{const lines=linesFor(section); return lines.length?`${section.title}\n${lines.map(line=>`• ${line}`).join('\n')}`:'';}).filter(Boolean); return `${header}${dateText?` (${dateText})`:''}\n\n${body.length?body.join('\n\n'):'No examination findings selected.'}`; }
function isNormalLine(line) { return /: (normal|no|none|negative|midline|full|equal and reactive|alert|down|2\+|−|5\/5 bilaterally)$/i.test(line); }
function marked(value,abnormal=true) { return abnormal?`**${value}**`:value; }
function sectionProse(title,lines) { if(!lines.length)return ''; const neutral=lines.filter(line=>/^Visual acuity:/.test(line)), assessed=lines.filter(line=>!neutral.includes(line)), abnormal=assessed.filter(line=>!isNormalLine(line)), detail=neutral.length?` ${neutral.join('; ')}.`:''; if(!assessed.length)return `${title}: ${neutral.join('; ')}.`; if(!abnormal.length)return `${title} was normal in the recorded domains.${detail}`; if(abnormal.length<assessed.length)return `${title} was normal apart from ${abnormal.map(line=>marked(line)).join('; ')}.${detail}`; return `${title}: ${abnormal.map(line=>marked(line)).join('; ')}.${detail}`; }
function powerProse() { const builder=document.querySelector('#motor .power-builder'); if(!builder)return ''; const tested=[]; builder.querySelectorAll('[data-power-row]').forEach(row=>{const name=row.dataset.name, normal=row.querySelector('[data-power-normal]').classList.contains('selected'), r=row.querySelector('[data-power-score][data-key$="-r"]').value, l=row.querySelector('[data-power-score][data-key$="-l"]').value; if(normal||r||l)tested.push({name,normal:normal||(r==='5'&&l==='5'),r,l});}); if(!tested.length)return ''; const upper=tested.some(item=>['Shoulder','Elbow','Wrist','Finger','APB','FDI','ADM'].some(part=>item.name.startsWith(part))), lower=tested.some(item=>['Hip','Knee','Ankle','Plantarflexion'].some(part=>item.name.startsWith(part))); const scope=upper&&lower?'Upper and lower limb power':upper?'Upper limb power':lower?'Lower limb power':'Power'; const weak=[]; tested.filter(item=>!item.normal).forEach(item=>{if(item.r&&item.r!=='5')weak.push(`right ${item.name.toLowerCase()} weakness (${item.r}/5)`); if(item.l&&item.l!=='5')weak.push(`left ${item.name.toLowerCase()} weakness (${item.l}/5)`);}); if(!weak.length)return `${scope} was normal in the tested muscle groups.`; const normalCount=tested.filter(item=>item.normal).length; return normalCount?`${scope} was normal apart from ${weak.map(item=>marked(item)).join(' and ')}.`:`${scope} showed ${weak.map(item=>marked(item)).join(' and ')}.`; }
function coordinationProse(lines) { const ataxia=lines.filter(line=>/ataxia/i.test(line)); if(!ataxia.length)return sectionProse('Coordination',lines); const sides=[...new Set(ataxia.map(line=>line.match(/:\s*([RL]) ataxia/i)?.[1]).filter(Boolean))], side=sides.length===2?'bilateral':sides[0]==='R'?'right-sided':sides[0]==='L'?'left-sided':''; const tests=[...new Set(ataxia.map(line=>line.startsWith('Finger–nose')?'finger–nose':line.startsWith('Heel–shin')?'heel–shin':'coordination'))], testText=tests.length===2?'finger–nose and heel–shin':tests.join(' and '); const extras=lines.filter(line=>!ataxia.includes(line)&&!isNormalLine(line)); return `Coordination was abnormal with ${marked(`${side?`${side} `:''}appendicular ataxia on ${testText} testing`)}.${extras.length?` ${extras.map(line=>marked(line)).join('; ')}.`:''}`; }
function proseNote(header,dateText) { const findings=[]; const mental=linesFor(sections[0]); if(mental.length)findings.push(sectionProse('Mental status',mental)); const cranial=linesFor(sections[1]); if(cranial.length)findings.push(sectionProse('Cranial nerve examination',cranial)); const motor=linesFor(sections[2]).filter(line=>!POWER_ORDER.some(name=>line.startsWith(`${name}:`))&&!line.startsWith('Power:')); const motorParts=[sectionProse('Motor examination',motor),powerProse()].filter(Boolean); if(motorParts.length)findings.push(motorParts.join(' ')); const reflexes=linesFor(sections[3]);if(reflexes.length)findings.push(sectionProse('Reflexes',reflexes)); const coordination=linesFor(sections[4]);if(coordination.length)findings.push(coordinationProse(coordination)); ['Sensation','Gait'].forEach((title,index)=>{const lines=linesFor(sections[index+5]);if(lines.length)findings.push(sectionProse(title,lines));}); return `${header}${dateText?` (${dateText})`:''}\n\n${findings.length?findings.join('\n\n'):'No examination findings selected.'}`; }
function previewHtml(markdown) { return escapeHtml(markdown).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>'); }
function historyForNote(){return historyRaw.value.trim();}
function formatNoteStyle(note){const headings=new Map([['presenting complaint','Presenting Complaint'],['history of presenting illness','History of Presenting Illness'],['associated symptoms','Associated Symptoms'],['relevant background','Relevant Background'],['medications and allergies','Medications and Allergies'],['social history','Social History'],['family history','Family History'],['investigations','Investigations'],['impression','Impression'],['plan','Plan']]);return note.trim().split('\n').map(line=>{const trimmed=line.trim(),heading=headings.get(trimmed.replace(/:$/,'').toLowerCase());if(heading)return heading;if(/^[-*•]\s+/.test(trimmed))return `• ${trimmed.replace(/^[-*•]\s+/,'')}`;return trimmed;}).join('\n');}
function splitClinicalNoteForExam(note){
  const lines=note.trim().split('\n');
  const headingIndex=lines.findIndex(line=>/^(assessment\s*(?:\/|&|and)?\s*plan|impression\s*(?:\/|&|and)?\s*plan|impression|plan)\s*:?$/i.test(line.trim()));
  if(headingIndex>=0)return {before:lines.slice(0,headingIndex).join('\n').trim(),after:lines.slice(headingIndex).join('\n').trim()};
  const paragraphs=note.trim().split(/\n\s*\n/);
  let planIndex=paragraphs.findIndex(paragraph=>/^(?:plan\s*(?:is|:)|management\s+plan\s*(?:is|:)|impression\s*(?:is|:)|assessment\s*(?:is|:)|we\s+will\s+(?:arrange|request|start|refer|review))/i.test(paragraph.trim()));
  if(planIndex>0&&/^(?:overall|in summary|impression|assessment)/i.test(paragraphs[planIndex-1].trim()))planIndex-=1;
  if(planIndex>=0)return {before:paragraphs.slice(0,planIndex).join('\n\n').trim(),after:paragraphs.slice(planIndex).join('\n\n').trim()};
  const inlinePlan=/\b(?:plan\s+(?:is|:)|management\s+plan\s+(?:is|:)|we\s+will\s+(?:arrange|request|start|refer|review))/i.exec(note);
  if(!inlinePlan)return {before:note.trim(),after:''};
  const beforePlan=note.slice(0,inlinePlan.index);
  const impressionStarts=[...beforePlan.matchAll(/\b(?:overall,|in\s+summary,|impression\s*(?:is|:)|assessment\s*(?:is|:))/gi)];
  const splitAt=impressionStarts.length?impressionStarts.at(-1).index:inlinePlan.index;
  return {before:note.slice(0,splitAt).trim(),after:note.slice(splitAt).trim()};
}
function setDictationStatus(message){dictationStatus.textContent=message;}
let speechRecognition=null, dictationBase='';
function supportsDictation(){return Boolean(window.SpeechRecognition||window.webkitSpeechRecognition);}
function stopDictation(){if(!speechRecognition)return;speechRecognition.stop();}
function startDictation(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){setDictationStatus('Dictation is not available in this browser. You can still type or paste the history.');return;}dictationBase=historyRaw.value.trim();speechRecognition=new Recognition();speechRecognition.continuous=true;speechRecognition.interimResults=true;speechRecognition.lang=navigator.language||'en-GB';speechRecognition.onstart=()=>{dictateButton.classList.add('recording');dictateButton.textContent='Stop dictation';dictateButton.setAttribute('aria-pressed','true');setDictationStatus('Listening… speak naturally.');};speechRecognition.onresult=event=>{let finalText='',interimText='';for(let i=event.resultIndex;i<event.results.length;i++){if(event.results[i].isFinal)finalText+=event.results[i][0].transcript;else interimText+=event.results[i][0].transcript;}if(finalText){dictationBase=`${dictationBase}${dictationBase?' ':''}${finalText.trim()}`;historyRaw.value=dictationBase;save();}setDictationStatus(interimText?`Listening: ${interimText}`:'Listening… speak naturally.');};speechRecognition.onerror=event=>{setDictationStatus(event.error==='not-allowed'?'Microphone access was not allowed.':`Dictation stopped: ${event.error}.`);};speechRecognition.onend=()=>{dictateButton.classList.remove('recording');dictateButton.textContent='Start dictation';dictateButton.setAttribute('aria-pressed','false');if(dictationStatus.textContent.startsWith('Listening'))setDictationStatus('Dictation stopped. Review the captured text.');speechRecognition=null;};speechRecognition.start();}
async function formatHistory(){const history=historyRaw.value.trim();if(!history){setDictationStatus('Add or dictate some clinical information first.');historyRaw.focus();return;}formatHistoryButton.disabled=true;formatHistoryButton.textContent='Structuring…';setDictationStatus('Organising the clinical note…');try{const response=await fetch('/api/format-history',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({history})});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.error||'Unable to structure the clinical note.');historyFormatted.value=payload.history||'';formattedHistoryWrap.hidden=!historyFormatted.value.trim();setDictationStatus('AI-edited note ready — review and edit it.');save();}catch(error){setDictationStatus(error.message||'Unable to structure the clinical note.');}finally{formatHistoryButton.disabled=false;formatHistoryButton.textContent='Structure note with AI';}}
function generateNote() { save(); const header=document.querySelector('#patient').value.trim()?`Neurology note — ${document.querySelector('#patient').value.trim()}`:'Neurology note'; const date=document.querySelector('#exam-date').value, dateText=date?new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'', examNote=generateBulletNote(header,dateText), clinicalNote=formatNoteStyle(historyForNote()), separator=examNote.indexOf('\n\n'), examBody=separator>=0?examNote.slice(separator+2):examNote; if(!clinicalNote){noteOutput.value=examNote;}else{const {before,after}=splitClinicalNoteForExam(clinicalNote), parts=[`${header}${dateText?` (${dateText})`:''}`,before?`Clinical Note\n${before}`:'',`Examination\n\n${examBody}`,after].filter(Boolean);noteOutput.value=parts.join('\n\n');} notePanel.hidden=false; notePanel.scrollIntoView({behavior:'smooth',block:'start'}); }
