let activeSensoryStroke=null;
function sensoryPoint(event,canvas) { const point=canvas.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const transformed=point.matrixTransform(canvas.getScreenCTM().inverse());return [Math.max(0,Math.min(150,Math.round(transformed.x*10)/10)),Math.max(0,Math.min(156,Math.round(transformed.y*10)/10))]; }
