function strokeSvg(stroke) { return `<polyline class="sensory-stroke" points="${stroke.points.map(point=>point.join(',')).join(' ')}"/>`; }
document.addEventListener('pointerdown',event=>{const canvas=event.target.closest('[data-sensory-draw]');if(!canvas)return;const drawing=canvas.closest('.sensory-drawing'),finding=drawing.querySelector('[data-sensory-drawing-finding].active')?.dataset.sensoryDrawingFinding,modality=drawing.querySelector('[data-sensory-modality].active')?.dataset.sensoryModality;if(!finding||!modality)return;event.preventDefault();const stroke={view:canvas.dataset.view,modality,finding,points:[sensoryPoint(event,canvas)]};activeSensoryStroke={canvas,drawing,stroke};const mark=document.createElementNS('http://www.w3.org/2000/svg','polyline');mark.classList.add('sensory-stroke');mark.setAttribute('points',stroke.points[0].join(','));canvas.querySelector('[data-sensory-strokes]').append(mark);activeSensoryStroke.mark=mark;canvas.setPointerCapture?.(event.pointerId);});
