function clearSectionNormal(section){
  section.querySelectorAll('input[type=radio],input[data-multi-key]').forEach(input=>input.checked=false);
  section.querySelectorAll('.other-wrap').forEach(wrap=>wrap.hidden=true);
  section.querySelectorAll('.visual-row').forEach(row=>row.querySelectorAll('.quadrant,.visual-normal,.visual-other').forEach(el=>el.classList.remove('selected')));
  section.querySelectorAll('.exam-table select').forEach(select=>select.value='');
  section.querySelectorAll('[data-power-normal]').forEach(normal=>{normal.classList.remove('selected');normal.closest('[data-power-row]').querySelectorAll('[data-power-score]').forEach(score=>score.value='');});
  unsetSectionNormal(section);
}
function setSectionNormal(section){
  const defaults=ROUTINE_NORMALS[section.id]||{};
  section.querySelectorAll('input[type=radio],input[data-multi-key]').forEach(input=>input.checked=defaults[input.dataset.label]===input.value);
  section.querySelectorAll('textarea[data-key],input:not([type=hidden])[data-key]').forEach(input=>input.value='');
  section.querySelectorAll('[data-visual-glasses]').forEach(button=>button.classList.remove('selected'));
  section.querySelectorAll('.other-wrap').forEach(wrap=>wrap.hidden=true);
  section.querySelectorAll('.visual-row').forEach(row=>{const normal=row.querySelector('.visual-normal');row.querySelectorAll('.quadrant,.visual-normal,.visual-other').forEach(el=>el.classList.remove('selected'));if(defaults['Visual fields']==='Normal')normal?.classList.add('selected');});
  section.querySelectorAll('.exam-table select').forEach(select=>select.value=defaults[select.dataset.label]||'');
  section.querySelectorAll('[data-power-normal]').forEach(normal=>{const selected=section.id==='motor'&&normal.closest('.power-pane')?.dataset.pane==='screen';normal.classList.toggle('selected',selected);normal.closest('[data-power-row]').querySelectorAll('[data-power-score]').forEach(score=>score.value='');});
  const button=section.querySelector('.section-normal');if(button){button.classList.add('selected');button.textContent='Clear routine normal';}
}
